<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class CommercialDocument extends Model {protected $fillable=['document_number','type','customer_id','source_document_id','issue_date','due_date','valid_until','discount','tax_rate','subtotal','tax_amount','total_amount','paid_amount','balance_amount','currency','payment_method','status','notes','created_by','stock_applied_at']; protected $casts=['issue_date'=>'date','due_date'=>'date','valid_until'=>'date','discount'=>'decimal:2','tax_rate'=>'decimal:2','subtotal'=>'decimal:2','tax_amount'=>'decimal:2','total_amount'=>'decimal:2','paid_amount'=>'decimal:2','balance_amount'=>'decimal:2','stock_applied_at'=>'datetime']; public function customer():BelongsTo{return $this->belongsTo(Customer::class);} public function source():BelongsTo{return $this->belongsTo(self::class,'source_document_id');} public function lines():HasMany{return $this->hasMany(CommercialDocumentLine::class);} public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function sourceDocument():BelongsTo{return $this->belongsTo(self::class,'source_document_id');}}
